package com.neonetwork; 

import android.app.Activity; 
import android.os.Bundle;
import android.view.View;
import android.view.Window; // Yeh import karna zaroori hai
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.TextView;
import android.widget.Toast;

public class login extends Activity { 

    // Layouts
    private LinearLayout layoutLogin, layoutRegister;

    // Login Views
    private EditText etLoginEmail, etLoginPassword;
    private Button btnLogin;
    private TextView tvForgotPassword, tvGoToRegister;

    // Register Views
    private EditText etRegisterName, etRegisterEmail, etRegisterMobile, etRegisterPassword;
    private Button btnRegister;
    private TextView tvGoToLogin;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        // App ko bina Title Bar (Toolbar) ke dikhane ke liye
        requestWindowFeature(Window.FEATURE_NO_TITLE);

        setContentView(R.layout.login); 

        // 1. Views ko initialize karna
        initViews();

        // 2. Click actions lagana
        setupClickListeners();
    }

    private void initViews() {
        layoutLogin = findViewById(R.id.layout_login);
        layoutRegister = findViewById(R.id.layout_register);

        etLoginEmail = findViewById(R.id.et_login_email);
        etLoginPassword = findViewById(R.id.et_login_password);
        btnLogin = findViewById(R.id.btn_login);
        tvForgotPassword = findViewById(R.id.tv_forgot_password);
        tvGoToRegister = findViewById(R.id.tv_go_to_register);

        etRegisterName = findViewById(R.id.et_register_name);
        etRegisterEmail = findViewById(R.id.et_register_email);
        etRegisterMobile = findViewById(R.id.et_register_mobile);
        etRegisterPassword = findViewById(R.id.et_register_password);
        btnRegister = findViewById(R.id.btn_register);
        tvGoToLogin = findViewById(R.id.tv_go_to_login);
    }

    private void setupClickListeners() {

        tvGoToRegister.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                layoutLogin.setVisibility(View.GONE);
                layoutRegister.setVisibility(View.VISIBLE);
            }
        });

        tvGoToLogin.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                layoutRegister.setVisibility(View.GONE);
                layoutLogin.setVisibility(View.VISIBLE);
            }
        });

        btnLogin.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                String email = etLoginEmail.getText().toString().trim();
                String password = etLoginPassword.getText().toString().trim();

                if (email.isEmpty() || password.isEmpty()) {
                    Toast.makeText(login.this, "Please enter Email and Password", Toast.LENGTH_SHORT).show();
                } else {
                    Toast.makeText(login.this, "Logging in...", Toast.LENGTH_SHORT).show();
                }
            }
        });

        btnRegister.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                String name = etRegisterName.getText().toString().trim();
                String email = etRegisterEmail.getText().toString().trim();
                String mobile = etRegisterMobile.getText().toString().trim();
                String password = etRegisterPassword.getText().toString().trim();

                if (name.isEmpty() || email.isEmpty() || mobile.isEmpty() || password.isEmpty()) {
                    Toast.makeText(login.this, "Please fill all details", Toast.LENGTH_SHORT).show();
                } else {
                    Toast.makeText(login.this, "Account Created Successfully!", Toast.LENGTH_SHORT).show();

                    layoutRegister.setVisibility(View.GONE);
                    layoutLogin.setVisibility(View.VISIBLE);
                }
            }
        });

        tvForgotPassword.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                Toast.makeText(login.this, "Forgot Password clicked", Toast.LENGTH_SHORT).show();
            }
        });
    }
}
